create table xxventuri.xxeba_email_templates_t (
    template_id   number,
    template_name varchar2(100 byte),
    description   varchar2(1000 byte),
    subject       varchar2(1000 byte),
    mail_content  clob,
    status        char(1 byte),
    created_by    varchar2(255 byte),
    created_date  timestamp(6),
    updated_by    varchar2(255 byte),
    updated_date  timestamp(6)
);

alter table xxventuri.xxeba_email_templates_t
    add constraint xxeba_email_templates_pk primary key ( template_id )
        using index enable;


